const candidates = new Map(FORMAL_DAILY_CHALLENGE_CATALOG.flatMap(stage => [1,2,3].flatMap(difficulty =>
  stage.difficulties[difficulty as FormalDailyChallengeDifficulty].candidates.map(candidate => [candidate.formalId,candidate] as const))));
export const getFormalDailyChallengeStage = (stageKey: string): FormalDailyChallengeStage | undefined => FORMAL_DAILY_CHALLENGE_CATALOG.find(stage => stage.stageKey === stageKey);
export const getFormalDailyChallengeCandidate = (formalId: string): FormalDailyChallengeCandidate | undefined => candidates.get(formalId);
export const getFormalDailyChallengeLevel = (formalId: string): LevelSpec | undefined => {
  const candidate = candidates.get(formalId); return candidate ? clonePlainData(candidate.level) : undefined;
};
export const getFormalDailyChallengeAssignments = (stageKey: string, difficulty: FormalDailyChallengeDifficulty) =>
  getFormalDailyChallengeStage(stageKey)?.difficulties[difficulty].candidates.map(({ level: _level, formalId, ...metadata }) =>
    ({ ...metadata, id: formalId, catalogRevision: FORMAL_DAILY_CHALLENGE_REVISION }));
